/// <summary>
/// DebuC 17.11.22
/// </summary>
/// <param name = "zertTable">NDXZertTable</param>
/// <param name = "selectedCertifications">NDXZertTable</param>
public void assignCertification(NDXZertTable zertTable, NDXZertTable selectedCertifications)
{
    MultiSelectionHelper  multiSelectionHelper = MultiSelectionHelper::construct();
    NDXZertTable currentZertTable;
    NDXZertZertZuordnung zertZertZuordnung;
    RecordInsertList    recordInsertList;
    ;

    if(!selectedCertifications || !FormDataUtil::isFormDataSource(selectedCertifications))
    {
        throw Error("@NDX:NDXInvalidSelection");
    }
    recordInsertList = new RecordInsertList(tableNum(NDXZertZertZuordnung));
    multiSelectionHelper.parmDatasource(FormDataUtil::getFormDataSource(selectedCertifications));
    currentZertTable = multiSelectionHelper.getFirst();

    while(currentZertTable)
    {
        zertZertZuordnung.MasterZertId = zertTable.ZertId;
        zertZertZuordnung.SlaveZertId  = currentZertTable.ZertId;
        recordInsertList.add(zertZertZuordnung);
        currentZertTable = multiSelectionHelper.getNext();
    }
    recordInsertList.insertDatabase();
}

/// <summary>
/// DebuC
/// </summary>
/// <param name = "zertZertZuordnung">NDXZertZertZuordnung</param>
public void reassignCertification(NDXZertZertZuordnung zertZertZuordnung)
{
    MultiSelectionHelper multiSelectionHelper = MultiSelectionHelper::construct();
    NDXZertZertZuordnung currentZertZertZuordnung;
    ;

    if(!zertZertZuordnung || !FormDataUtil::isFormDataSource(zertZertZuordnung))
    {
        throw Error("@NDX:NDXInvalidSelection");
    }

    currentZertZertZuordnung = multiSelectionHelper.getFirst();
    while(currentZertZertZuordnung)
    {
        currentZertZertZuordnung.delete();
        currentZertZertZuordnung = multiSelectionHelper.getNext();
    }
}
